import {escapeHtml as e} from '../lib/sites.mjs';
import {FIELD_TYPES,documentText,documentSummary,substitute} from '../lib/document-core.mjs';
import {listDocumentRecords,getDocumentRecord,addDocumentTemplate,updateDocumentTemplate,addStudioDocument,updateStudioDocument,restoreStudioRevision,duplicateStudioDocument,removeDocumentRecord} from '../lib/document-store.mjs';
import {makeDocumentPdf,savePdf} from '../lib/document-pdf.mjs';
import {governmentRecords} from './government-page.mjs';
let records=[],tab='documents',previewVersion=null,previewDocId=null;
const attr=x=>e(String(x??''));
export const documentRecords=()=>records;
export async function refreshDocuments(){records=await listDocumentRecords();return records;}
const filtered=(profile,type)=>records.filter(r=>r.profileId===profile&&r.type===type);
const titleOf=r=>documentSummary(r).title;
const departments=profile=>governmentRecords().filter(r=>r.profileId===profile&&r.type==='department');
const deptOptions=(profile,current='')=>`<option value="">Без ведомства</option>${departments(profile).map(d=>`<option value="${attr(d.id)}" ${d.id===current?'selected':''}>${e(d.name)} — ${e(d.officer)}</option>`).join('')}`;
const btn=(action,label,id='',className='secondary')=>`<button type="button" class="button ${className}" data-document-action="${attr(action)}" ${id?`data-id="${attr(id)}"`:''}>${e(label)}</button>`;
export function documentSection(state){const profile=state.activeProfileId,docs=filtered(profile,'document'),templates=filtered(profile,'template');return `<div class="stack"><section class="card"><div class="row spread"><div><h3>Document Studio</h3><p class="subtle">Локальный редактор, формы, шаблоны, версии и PDF. Данные принадлежат выбранному RP-серверу.</p></div><div class="row"><span class="tag">Документов: ${docs.length}</span><span class="tag">Шаблонов: ${templates.length}</span></div></div><div class="row">${btn('new-document','+ Пустой документ','','primary')}${btn('new-template','+ Шаблон')}</div></section><section class="card"><div class="row">${btn('tab-documents','Документы', '', tab==='documents'?'primary':'secondary')}${btn('tab-templates','Шаблоны','',tab==='templates'?'primary':'secondary')}</div></section>${tab==='documents'?`<section class="card"><h3>Документы (${docs.length})</h3>${docs.map(d=>{const v=d.versions.at(-1);return `<article class="studio-item"><div><strong>${e(v.title)}</strong><p class="subtle">Версия ${d.currentVersion} · ${e(d.updatedAt.slice(0,16).replace('T',' '))} · ${e(departments(profile).find(x=>x.id===v.departmentId)?.name||'Личный документ')}</p><p class="subtle">${e(documentText(d).slice(0,200))}</p></div><div class="row">${btn('view','Просмотр / PDF',d.id)}${btn('edit-document','Редактировать',d.id)}${btn('versions','История',d.id)}${btn('duplicate','Копия',d.id)}${btn('delete','Удалить',d.id,'danger')}</div></article>`;}).join('')||'<p class="empty">Создайте пустой документ или заполните форму выбранного шаблона.</p>'}</section>`:`<section class="card"><h3>Шаблоны (${templates.length})</h3>${templates.map(t=>`<article class="studio-item"><div><strong>${e(t.title)}</strong><p class="subtle">${e(t.category)} · ${t.fields.length} полей · ${e(t.body.slice(0,210))}</p></div><div class="row">${btn('from-template','Заполнить форму',t.id,'primary')}${btn('edit-template','Изменить',t.id)}${btn('delete','Удалить',t.id,'danger')}</div></article>`).join('')||'<p class="empty">Создайте шаблон и добавьте в него поля формы. Они подставляются через {{имя_поля}}.</p>'}</section>`}</div>`;}
function modal(id,title,inner){document.getElementById('studio-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='studio-dialog';dialog.className='gov-dialog studio-dialog';dialog.innerHTML=`<div class="stack"><div class="row spread"><h3>${e(title)}</h3>${btn('close','Закрыть')}</div>${inner}</div>`;document.body.appendChild(dialog);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();return dialog;}
function fieldsRow(field={key:'',label:'',type:'text',required:false,options:[]}){return `<div class="studio-field-row" data-studio-field><label>Ключ (латиница)<input name="fieldKey" maxlength="40" value="${attr(field.key)}" placeholder="case_number" required></label><label>Название<input name="fieldLabel" maxlength="90" value="${attr(field.label)}" required></label><label>Тип<select name="fieldType">${Object.entries(FIELD_TYPES).map(([key,label])=>`<option value="${key}" ${key===field.type?'selected':''}>${label}</option>`).join('')}</select></label><label>Варианты списка (каждый с новой строки)<textarea name="fieldOptions" rows="2" maxlength="900">${e(field.options.join('\n'))}</textarea></label><label class="check"><input type="checkbox" name="fieldRequired" ${field.required?'checked':''}> Обязательное</label>${btn('remove-field','Удалить поле','','danger')}</div>`;}
function templateDialog(profile,row){return modal('studio-dialog',row?'Редактирование шаблона':'Новый шаблон',`<form id="document-form" data-type="template" data-id="${attr(row?.id||'')}" class="stack"><label>Название<input name="title" required maxlength="180" value="${attr(row?.title||'')}"></label><label>Категория<input name="category" required maxlength="90" value="${attr(row?.category||'Процессуальный документ')}"></label><label>Ведомство<select name="departmentId">${deptOptions(profile,row?.departmentId)}</select></label><label>Содержание и переменные<textarea name="body" required maxlength="60000" rows="10" placeholder="Постановление № {{number}}">${e(row?.body||'ПОСТАНОВЛЕНИЕ\n№ {{number}}\n\n{{description}}')}</textarea></label><h4>Поля формы</h4><p class="subtle">Используйте в содержании запись {{ключ_поля}}. При заполнении она заменится введённым значением.</p><div id="studio-fields">${(row?.fields??[{key:'number',label:'Номер',type:'text',required:true,options:[]},{key:'description',label:'Текст постановления',type:'textarea',required:true,options:[]}]).map(fieldsRow).join('')}</div>${btn('add-field','+ Добавить поле')}<div class="dialog-actions"><button type="submit" class="button primary">Сохранить шаблон</button></div></form>`);}
function valueControl(f,value=''){const common=`name="value_${attr(f.key)}" data-value-key="${attr(f.key)}" ${f.required?'required':''}`;const rendered=f.type==='textarea'?`<textarea ${common} maxlength="6000" rows="3">${e(value)}</textarea>`:f.type==='select'?`<select ${common}><option value="">— Выберите —</option>${f.options.map(s=>`<option value="${attr(s)}" ${s===value?'selected':''}>${e(s)}</option>`).join('')}</select>`:`<input ${common} ${f.type==='date'?'type="date"':f.type==='number'?'type="text" inputmode="decimal"':'type="text"'} maxlength="6000" value="${attr(value)}">`;return `<label>${e(f.label)}${f.required?' *':''}${rendered}</label>`;}
function documentDialog(profile,record=null,template=null){const current=record?.versions.at(-1),formFields=current?.fields||template?.fields||[],body=current?.body||template?.body||'',title=current?.title||template?.title||'Новый документ';const content=record?'Редактирование документа':template?'Заполнение шаблона':'Новый документ';
 const d=modal('studio-dialog',content,`<form id="document-form" data-type="document" data-id="${attr(record?.id||'')}" data-template-id="${attr(current?.templateId||template?.id||'')}" class="stack"><label>Название документа<input name="title" maxlength="180" required value="${attr(title)}"></label><label>Ведомство<select name="departmentId">${deptOptions(profile,current?.departmentId||template?.departmentId||'')}</select></label><label>Текст документа<textarea name="body" required maxlength="60000" rows="10">${e(body||'Заголовок\n\nТекст документа')}</textarea></label><div class="studio-note">Текст поддерживает переменные вида {{number}}. Для изменения структуры полей редактируйте шаблон и создавайте новый документ. Данные существующего документа не меняются.</div><h4>Поля документа</h4><div id="studio-doc-fields">${formFields.map(f=>valueControl(f,current?.values[f.key]??'')).join('')||'<p class="subtle">Документ без переменных.</p>'}</div><h4>Предварительный просмотр</h4><pre class="gov-preview studio-preview" id="studio-live-preview"></pre><div class="dialog-actions"><button type="submit" class="button primary">${record?'Сохранить новую версию':'Создать документ'}</button></div></form>`);
 d._fields=formFields;previewForm(d);return d;}
function formData(doc){const form=doc.querySelector('#document-form'),data=new FormData(form),values={};for(const f of doc._fields||[])values[f.key]=data.get('value_'+f.key)??'';return {title:data.get('title'),body:data.get('body'),departmentId:data.get('departmentId'),templateId:form.dataset.templateId||'',fields:doc._fields||[],values};}
function previewForm(doc){const area=doc.querySelector('#studio-live-preview');if(!area)return;try{const data=formData(doc);area.textContent=substitute(data.body,data.values);}catch(err){area.textContent=err.message;}}
function collectDesignerFields(dialog){return [...dialog.querySelectorAll('[data-studio-field]')].map(row=>({key:row.querySelector('[name=fieldKey]').value,label:row.querySelector('[name=fieldLabel]').value,type:row.querySelector('[name=fieldType]').value,required:row.querySelector('[name=fieldRequired]').checked,options:row.querySelector('[name=fieldOptions]').value.split('\n').map(x=>x.trim()).filter(Boolean)}));}
function pdfFilename(title,version){return `majestictoolkit-${title.toLowerCase().replace(/[^a-z0-9_-]+/g,'-').slice(0,35)||'document'}-v${version}.pdf`;}
function viewer(record,number){const version=record.versions.find(v=>v.number===number);if(!version)throw Error('Версия отсутствует');previewDocId=record.id;previewVersion=number;return modal('studio-dialog',`Просмотр документа · v${number}`,`<p class="subtle">${e(version.title)} · ${e(version.createdAt)} · версия ${number} из ${record.versions.length}</p><pre class="gov-preview studio-preview">${e(documentText(record,number))}</pre><div class="row">${btn('copy-preview','Копировать текст')}${btn('pdf','Скачать PDF','','primary')}${btn('history','История версий')}</div>`);}
function history(record){const lines=record.versions.slice().reverse().map(v=>`<div class="studio-version"><div><strong>Версия ${v.number}</strong> · ${e(v.title)}<p class="subtle">${e(v.createdAt)}</p></div><div class="row">${btn('view-version','Просмотр',String(v.number))}${btn('restore-version','Восстановить',String(v.number),'secondary')}</div></div>`).join('');previewDocId=record.id;modal('studio-dialog',`История · ${record.versions.at(-1).title}`,`<p class="subtle">Восстановление создаст новую версию, не удаляя предыдущие.</p>${lines}`);}
function ensureProfile(row,profile){if(row.profileId!==profile)throw Error('Запись относится к другому серверу');}
export async function handleDocumentAction(button,state,render,feedback){const action=button.dataset.documentAction,profile=state.activeProfileId,id=button.dataset.id,profiles=state.profiles.map(p=>p.id),government=governmentRecords();
 if(action==='close'){button.closest('dialog')?.close();return;}
 if(action==='tab-documents'||action==='tab-templates'){tab=action==='tab-documents'?'documents':'templates';render();return;}
 if(action==='new-template'){templateDialog(profile);return;}
 if(action==='new-document'){documentDialog(profile);return;}
 if(action==='add-field'){document.getElementById('studio-fields').insertAdjacentHTML('beforeend',fieldsRow());return;}
 if(action==='remove-field'){button.closest('[data-studio-field]')?.remove();return;}
 if(action==='edit-template'||action==='edit-document'||action==='from-template'){
  const row=await getDocumentRecord(id);ensureProfile(row,profile);
  if(action==='edit-template'&&row.type==='template')templateDialog(profile,row);
  else if(action==='from-template'&&row.type==='template')documentDialog(profile,null,row);
  else if(action==='edit-document'&&row.type==='document')documentDialog(profile,row);
  else throw Error('Некорректный тип записи');return;}
 if(['view','versions','duplicate','delete'].includes(action)){const row=await getDocumentRecord(id);ensureProfile(row,profile);
  if(action==='view'){viewer(row,row.currentVersion);return;}
  if(action==='versions'){history(row);return;}
  if(action==='duplicate'){if(row.type!=='document')throw Error('Не документ');await duplicateStudioDocument(id,profiles,government);await refreshDocuments();render();feedback('Создана независимая копия документа');return;}
  if(!confirm(`Удалить «${titleOf(row)}»?`))return;await removeDocumentRecord(id);await refreshDocuments();render();feedback('Запись удалена');return;}
 if(action==='view-version'||action==='restore-version'){const number=Number(id),row=await getDocumentRecord(previewDocId);ensureProfile(row,profile);if(action==='view-version'){viewer(row,number);return;}if(!confirm(`Восстановить версию ${number}? Будет создана новая версия.`))return;await restoreStudioRevision(row.id,number,profiles,government);document.getElementById('studio-dialog')?.close();await refreshDocuments();render();feedback('Создана новая версия из выбранной редакции');return;}
 if(action==='history'){const row=await getDocumentRecord(previewDocId);ensureProfile(row,profile);history(row);return;}
 if(action==='copy-preview'||action==='pdf'){const row=await getDocumentRecord(previewDocId);ensureProfile(row,profile);const text=documentText(row,previewVersion),v=row.versions.find(x=>x.number===previewVersion);if(action==='copy-preview'){await navigator.clipboard.writeText(text);feedback('Текст скопирован');return;}const pdf=makeDocumentPdf(v.title,text);savePdf(pdf,pdfFilename(v.title,v.number));feedback(`PDF сформирован: версия ${v.number}`);return;}
}
export async function handleDocumentSubmit(event,state,render,feedback){const form=event.target,dialog=form.closest('dialog'),profile=state.activeProfileId,all=state.profiles.map(p=>p.id),government=governmentRecords(),values=Object.fromEntries(new FormData(form).entries());
 if(form.dataset.type==='template'){const data={title:values.title,category:values.category,departmentId:values.departmentId,body:values.body,fields:collectDesignerFields(dialog)};const id=form.dataset.id;if(id){const row=await getDocumentRecord(id);ensureProfile(row,profile);await updateDocumentTemplate(id,data,all,government);}else await addDocumentTemplate(profile,data,all,government);}
 else if(form.dataset.type==='document'){const data=formData(dialog),id=form.dataset.id;if(id){const row=await getDocumentRecord(id);ensureProfile(row,profile);await updateStudioDocument(id,data,all,government);}else await addStudioDocument(profile,data,all,government);}
 else throw Error('Неизвестная форма Document Studio');dialog.close();await refreshDocuments();render();feedback('Данные Document Studio сохранены');}
export function handleDocumentInput(event){const dialog=event.target.closest('#studio-dialog');if(dialog?.querySelector('#document-form[data-type=document]'))previewForm(dialog);}
